const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let screen='wiki',activeDoc=1,layout='星图',aiOpen=true,side='ai',formatTab='排版设置',folder='全部简历',activeResume=null;
const nodes=[{title:'我的经历',type:0,text:'# 我的经历\n\n点击图谱中的节点阅读经历。'},{title:'基础信息',type:0,text:'# 基础信息\n\n在这里记录姓名、教育、联系方式等信息。'}];
let resumes=[];
let docTabs=[1],wikiRevision=0,wikiRelations=[],runId=null,outline=null,runDetail=null,runReview=null;
let wikiMessages={};
function selectedExperience(){const n=nodes[activeDoc];return n?.kind==='experience'?n.id:['story','fragment'].includes(n?.kind)?n.experience_id:null}
function openDoc(i){activeDoc=i;if(!docTabs.includes(i))docTabs.push(i);render();if(screen==='wiki')loadConversation()}
let folders=['我的简历','实习申请'];let opened=[];const current=()=>resumes.find(r=>r.id===activeResume);
function sample(){return '<h1>示例候选人</h1><div class="contact">产品实习生方向 · 邮箱@example.com · 此内容仅用于页面预览</div><h2>教育背景</h2><h3>示例大学 ｜ 本科</h3><p>相关课程、学习经历与专业背景。</p><h2>实习经历</h2><h3>示例公司 ｜ 产品实习生</h3><p>参与内容制作与工作流程优化，探索工具在实际工作中的应用。</p><ul><li><b>流程梳理：</b>整理团队协作中的重复步骤，明确各阶段需要交付的内容。</li><li><b>工具应用：</b>结合实际场景尝试新工具，完成内容制作与调整。</li></ul><h2>项目经历</h2><h3>个人项目 ｜ 设计与实现</h3><p>从具体问题出发，梳理需求、制作原型，并根据使用反馈调整方案。</p><h2>技能与资质</h2><p>文档表达 · 数据整理 · AI 工具应用</p>';}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3000)}
async function save(fromEditor=true){if(fromEditor&&current()&&$('#paper'))current().html=$('#paper').innerHTML;try{await postJson('/api/resumes',{items:resumes});toast('已保存到本机资料库')}catch(e){toast(`简历保存失败：${e.message}`)}}
function modal(title,body,action,label='确定'){$('#dialog').innerHTML=`<h2>${title}</h2>${body}<footer><button data-action="close">取消</button><button class="primary" data-action="${action}">${label}</button></footer>`;$('#dialog').showModal()}
function aiPanel(editor=false){return `<section class="panel ${editor?'side':'ai-panel'}"><div class="panel-head"><strong>✧ ${editor?'AI 帮写':'经历助手'}</strong><span>DeepSeek 已接入</span><button data-action="hide-ai" aria-label="关闭 AI 面板">×</button></div><div class="chat-messages"><div class="ai-avatar">✧</div><h3>${editor?'让 AI 帮你打磨简历':'从一段经历开始'}</h3><p>${editor?'告诉 AI 希望重点打磨的方向。AI 会阅读正文，把具体建议作为评论附在相关内容旁，由你决定如何处理。':'你可以讲述一段经历，或补充当前页面中的细节。'}</p><button class="suggestion" data-action="suggest">${editor?'审阅整份简历，指出表达不清楚的地方':'记录一段新的实习经历'}</button><button class="suggestion" data-action="suggest">${editor?'重点检查个人贡献是否突出':'补充当前经历的具体行动'}</button>${editor?'<button class="suggestion" data-action="demo-review">查看评论交互示例</button><small>预设示例，用于体验交互，不是 AI 审阅结果。</small>':''}${!editor?'<button class="suggestion" data-action="questions">根据这段经历引导提问</button>':''}<div id="messages"></div></div><div class="compose"><textarea id="chat" placeholder="${editor?'希望 AI 从哪些方面帮你打磨？':'输入你的想法…'}" aria-label="AI 输入"></textarea><div><span>模型建议需审阅确认</span><button class="primary" data-action="send" aria-label="发送">↑</button></div></div></section>`}
function reviewMarkup(){const r=current();if(!r?.review)return '';const demo=!r.review.suggestion;return `<aside class="review-rail" aria-label="AI 建议评论"><div class="comment"><strong>✧ AI 建议 ${demo?'· 交互示例':''}</strong><small>关联正文摘录</small><blockquote>${esc(r.review.quote)}</blockquote><p>${esc(r.review.suggestion||"这句话说明了工作方向，但具体交付还不够清楚。可以结合已有事实，补充整理的是哪些步骤、交付了什么，以及如何用于团队协作。")}</p>${demo?'<p class="review-note">预设交互示例，不是 AI 审阅结果。</p>':''}<button data-action="locate-review">定位原文</button><button data-action="resolve-review">标记已处理</button><button data-action="dismiss-review">忽略建议</button></div></aside>`}
function outlineView(value,run){const cards=(value.sections||[]).map(section=>`<section><h3>${esc(section.name)}</h3>${(section.items||[]).map(item=>`<article><strong>${esc(item.title||'待定条目')}</strong><p>写法：${esc(item.approach||'待定')} · 重点：${esc(item.focus||'待定')}</p></article>`).join('')||'<p>此栏暂无条目</p>'}</section>`).join('');const reasons=(run?.selection?.items||[]).map(item=>`<li>${esc(item.experience_title||item.section||'固定资料')}：${esc(item.reason||item.focus||'已选入')}</li>`).join('');const issues=(runReview?.issues||[]).map(issue=>`<li>${esc(issue.type||'校验')}：${esc(issue.reason||'需检查')}${issue.sentence?`<blockquote>${esc(issue.sentence)}</blockquote>`:''}</li>`).join('');return `${cards}<details><summary>查看选材依据</summary><ul>${reasons||'<li>暂无可选经历</li>'}</ul></details>${runReview?`<details open><summary>成稿待检查 · ${runReview.issues.length} 项</summary><ul>${issues}</ul><h3>待审正文</h3><pre>${esc(runReview.markdown||'')}</pre></details>`:''}`}
function render(){document.querySelectorAll('[data-go]').forEach(b=>b.classList.toggle('active',b.dataset.go===screen));$('#tabs').innerHTML=opened.map(id=>resumes.find(r=>r.id===id)).filter(Boolean).map(r=>`<button data-open="${r.id}" class="${screen==='editor'&&activeResume===r.id?'active':''}">${esc(r.name)} <span data-close-tab="${r.id}">×</span></button>`).join('');
if(screen==='wiki'){$('#app').innerHTML=`<div class="wiki"><section class="panel"><div class="panel-head"><strong>知识图谱</strong><span>${wikiRevision?`第 ${wikiRevision} 版 · `:'示例 · '}${nodes.length} 个节点</span></div><div class="graph" id="graph"></div><div class="legend">● 个人信息　<span style="color:#6d91bd">● 经历</span>　<span style="color:#c6a374">● 高光</span></div><div class="graph-footer">${['星图','球面','分层'].map(x=>`<button data-layout="${x}" class="${layout===x?'active':''}">${x}</button>`).join('')}<button data-action="reset">复原</button></div></section><section class="panel"><div class="doc-tabs" role="tablist" aria-label="经历文档标签">${docTabs.map(i=>`<div class="doc-tab ${i===activeDoc?'active':''}"><button role="tab" aria-selected="${i===activeDoc}" data-node="${i}">${esc(nodes[i].title)}</button><button data-close-doc="${i}" aria-label="关闭 ${esc(nodes[i].title)}">×</button></div>`).join('')}<button data-action="new-node" aria-label="新建经历">＋</button><button data-action="save-doc" aria-label="保存经历正文">保存</button>${!aiOpen?'<button data-action="show-ai">✧ AI</button>':''}</div>${activeDoc===null?'<div class="empty">点击图谱节点打开页面，或点击 ＋ 新建页面。</div>':`<div class="doc-title">${esc(nodes[activeDoc].title)}</div><div class="doc-sub">Markdown 文档 · 可编辑</div><textarea class="doc-editor" id="doc-editor" aria-label="经历正文">${esc(nodes[activeDoc].text)}</textarea><div class="foot">编辑后点击上方“保存”；索引与正文同步更新</div>`}</section>${aiOpen?aiPanel():''}</div>`;if(!aiOpen)$('.wiki').style.gridTemplateColumns='minmax(260px,1fr) minmax(300px,1.3fr)';graph();const chat=$('#chat');if(chat&&!selectedExperience()){chat.disabled=true;chat.placeholder='先在图谱中选择一段已有经历'}const messages=$('#messages');if(messages)messages.innerHTML=wikiMessages[selectedExperience()]||'';}
if(screen==='resumes'){$('#app').innerHTML=`<div class="library"><div class="heading"><div><h1>我的简历</h1><p>每一次机会，都有一份合适的表达。</p></div><div class="actions"><button data-action="folder">＋ 新建文件夹</button><button class="primary" data-action="new">＋ 新建简历</button></div></div><div class="folders">${['全部简历',...folders].map(x=>`<button data-folder="${esc(x)}" class="${folder===x?'active':''}">▱ ${esc(x)}</button>`).join('')}</div><div class="cards">${resumes.filter(r=>folder==='全部简历'||r.folder===folder).map(r=>`<article class="card" role="button" tabindex="0" data-open="${r.id}" aria-label="打开 ${esc(r.name)}"><div class="mini"><div class="mini-sheet"><b>${esc(r.name)}</b>${Array.from({length:17},(_,i)=>`<div class="mini-line ${i%5===0?'heading-line':i%3===0?'short':''}"></div>`).join('')}</div></div><div class="card-meta"><strong>${esc(r.name)}</strong><small>${esc(r.folder)} · 本地原型</small></div></article>`).join('')||'<div class="empty">这个文件夹还没有简历。</div>'}</div></div>`}
if(screen==='editor'&&current()){$('#app').innerHTML=`<div class="toolbar"><button data-action="save">保存</button><button data-action="copy">创建副本</button><button data-action="save-as">另存</button><button data-action="rename">重命名</button><div class="middle"><button data-action="format" class="${side==='format'?'active':''}">简历美化</button><button data-action="ai" class="${side==='ai'?'active':''}">✧ AI 帮写</button></div></div><div class="editor-space"><div class="paper-area"><article id="paper" class="paper" contenteditable="true" aria-label="简历正文">${current().html}</article>${side==='ai'?reviewMarkup():''}</div>${side==='ai'?aiPanel(true):side==='format'?formatPanel():''}</div>${outline?`<div class="outline-drawer"><strong>简历大纲 · 修订后用于正文生成</strong><button data-action="close-outline">×</button><div class="outline-content">${outlineView(outline,runDetail)}</div><textarea id="outline-comment" placeholder="对大纲提出修改意见…"></textarea><button data-action="revise-outline">提交意见并修订</button><button class="primary" data-action="compose-resume">根据大纲生成正文</button></div>`:''}`;}
if(screen==='editor'&&current()){Object.assign($('#paper').style,current().styles||{});document.querySelectorAll('[data-style]').forEach(el=>{const v=current().styles?.[el.dataset.style];if(v)el.value=parseFloat(v)})}
if(screen==='settings'||screen==='help')$('#app').innerHTML=screen==='settings'?`<div class="simple"><h2>资料同步</h2><p>工作台资料先保存在本机。使用私有仓库 AsteriaAnna/esume-Workbench-data 保存新工作台的备份版本。</p><label>GitHub 访问令牌<input id="sync-token" type="password" autocomplete="off" placeholder="粘贴可读写该私有仓库的令牌"></label><button data-action="sync-config">保存令牌</button><button data-action="sync-push">同步到私有仓库</button><button data-action="sync-pull">从私有仓库恢复到空资料库</button><p id="sync-status">正在读取同步状态…</p><p>令牌只保存在本机配置中。恢复操作只在本机资料库为空时执行。</p></div>`:`<div class="simple"><h2>使用说明</h2><p>经历库：点击图谱节点，在中栏编辑正文。简历：新建、打开并编辑简历，通过右侧面板查看写作与排版入口。</p><p>资料保存在本机，设置中可同步到私有仓库。</p><button data-go="wiki">返回经历库</button></div>`;
if(screen==='settings')loadSyncStatus();
}
function formatPanel(){return `<section class="panel side"><div class="panel-head"><strong>简历美化</strong><span></span><button data-action="hide-ai" aria-label="关闭侧栏">×</button></div><div class="side-body"><div class="switches">${['切换模板','排版设置','模块管理'].map(t=>`<button data-format="${t}" class="${formatTab===t?'active':''}">${t}</button>`).join('')}</div>${formatTab==='排版设置'?'<label class="field">字号 <input data-style="fontSize" type="range" min="11" max="18" value="13"></label><label class="field">行间距 <input data-style="lineHeight" type="range" min="1.2" max="2.4" step=".1" value="1.7"></label><label class="field">页面留白 <input data-style="padding" type="range" min="20" max="70" value="48"></label>':formatTab==='切换模板'?'<button class="suggestion" data-theme="classic">经典 · 清晰单栏</button><button class="suggestion" data-theme="blue">蓝调 · 标题强调</button>':'<p>本份简历的内容模块</p><button class="suggestion">教育背景</button><button class="suggestion">实习经历</button><button class="suggestion">项目经历</button><button class="suggestion">技能与资质</button><small>模块调整交互待设计。</small>'}</div></section>`}
function graph(){const svgNS='http://www.w3.org/2000/svg',host=$('#graph');host.innerHTML='<svg viewBox="0 0 600 600" aria-label="示例知识图谱"><g id="world"></g></svg>';const svg=host.firstChild,world=$('#world');let pan={x:0,y:0},scale=1,drag=null;const coords=nodes.map((n,i)=>layout==='分层'?{x:90+(i%3)*210,y:120+Math.floor(i/3)*170}:i===0?{x:300,y:300}:{x:300+Math.cos(i*1.047)*200,y:300+Math.sin(i*1.047)*(layout==='球面'?130:205)});const edges=[];const pairs=nodes.map((n,i)=>i===0?null:[n.experience_id?nodes.findIndex(x=>x.id===n.experience_id):0,i]).filter(Boolean);for(const rel of wikiRelations){if(rel.status!=='active'||rel.type!=='about_topic')continue;const from=nodes.findIndex(n=>n.id===rel.from_id),to=nodes.findIndex(n=>n.id===rel.to_id);if(from>=0&&to>=0)pairs.push([from,to])}for(const [from,to] of pairs){const line=document.createElementNS(svgNS,'line');world.append(line);edges.push({line,from,to})}const els=nodes.map((n,i)=>{const g=document.createElementNS(svgNS,'g');g.setAttribute('role','button');g.setAttribute('tabindex','0');g.setAttribute('aria-label',n.title);g.innerHTML=`<circle r="${i===activeDoc?13:9}" fill="${['#8990cb','#719bc5','#d4b17a'][n.type]}"></circle><text y="30">${esc(n.title)}</text>`;g.onkeydown=e=>{if(e.key==='Enter'){openDoc(i)}};g.onpointerdown=e=>{e.stopPropagation();drag={i,x:e.clientX,y:e.clientY,moved:false};svg.setPointerCapture(e.pointerId)};world.append(g);return g});function draw(){edges.forEach(({line,from,to})=>{for(const [k,v]of Object.entries({x1:coords[from].x,y1:coords[from].y,x2:coords[to].x,y2:coords[to].y}))line.setAttribute(k,v)});els.forEach((el,i)=>el.setAttribute('transform',`translate(${coords[i].x} ${coords[i].y})`));world.setAttribute('transform',`translate(${pan.x} ${pan.y}) scale(${scale})`)}function point(e){const p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;return p.matrixTransform(svg.getScreenCTM().inverse())}svg.onpointerdown=e=>{drag={i:-1,x:e.clientX,y:e.clientY,pan:{...pan},start:point(e)};svg.setPointerCapture(e.pointerId)};svg.onpointermove=e=>{if(!drag)return;const p=point(e);if(Math.abs(e.clientX-drag.x)+Math.abs(e.clientY-drag.y)>4)drag.moved=true;if(drag.i>=0)coords[drag.i]={x:(p.x-pan.x)/scale,y:(p.y-pan.y)/scale};else pan={x:drag.pan.x+p.x-drag.start.x,y:drag.pan.y+p.y-drag.start.y};draw()};svg.onpointerup=()=>{const d=drag;drag=null;if(d&&d.i>=0&&!d.moved){openDoc(d.i)}};svg.onpointercancel=()=>drag=null;svg.addEventListener('wheel',e=>{e.preventDefault();scale=Math.max(.4,Math.min(2.5,scale*(e.deltaY>0?.9:1.1)));draw()},{passive:false});draw()}
function openResume(id){activeResume=Number(id);if(!opened.includes(activeResume))opened.push(activeResume);screen='editor';side='ai';render()}
document.addEventListener('input',e=>{if(e.target.id==='doc-editor')nodes[activeDoc].text=e.target.value;if(e.target.id==='paper')current().html=e.target.innerHTML;if(e.target.dataset.style){const k=e.target.dataset.style;const v=e.target.value+(k==='lineHeight'?'':'px');$('#paper').style[k]=v;current().styles={...current().styles,[k]:v}}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.dataset.open)openResume(e.target.dataset.open)});
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-open],[data-close-tab]');if(!b)return;if(e.target.dataset.closeTab){opened=opened.filter(id=>id!==Number(e.target.dataset.closeTab));if(activeResume===Number(e.target.dataset.closeTab))screen='resumes';render();return}if(b.dataset.go){screen=b.dataset.go;render();return}if(b.dataset.open){openResume(b.dataset.open);return}if(b.dataset.closeDoc!==undefined){const id=Number(b.dataset.closeDoc),at=docTabs.indexOf(id);docTabs=docTabs.filter(i=>i!==id);if(activeDoc===id)activeDoc=docTabs[Math.min(at,docTabs.length-1)]??null;render();return}if(b.dataset.node!==undefined){openDoc(Number(b.dataset.node));return}if(b.dataset.layout){layout=b.dataset.layout;render();return}if(b.dataset.folder){folder=b.dataset.folder;render();return}if(b.dataset.format){formatTab=b.dataset.format;render();return}if(b.dataset.theme){const color=b.dataset.theme==='blue'?'#4563b3':'#26314a';$('#paper').style.color=color;current().styles={...current().styles,color};return}const a=b.dataset.action;
if(a==='reset')graph();if(a==='hide-ai'){if(screen==='wiki')aiOpen=false;else side='';render()}if(a==='show-ai'){aiOpen=true;render()}if(a==='format'||a==='ai'){side=a;render()}if(a==='close')$('#dialog').close();
if(a==='sync-config')saveSyncConfig();if(a==='sync-push')runSync('push');if(a==='sync-pull')runSync('pull');
if(a==='new')modal('新建简历','<label>简历名称<input id="name" placeholder="例如：产品实习生 · 公司名称"></label><label>目标 JD<textarea id="jd" placeholder="粘贴目标岗位说明，创建后生成可修改大纲"></textarea></label>','create','创建空白稿');
if(a==='create'){const jd=$('#jd')?.value.trim();const name=$('#name').value.trim()||'未命名简历';const r={id:Date.now(),name,folder:folder==='全部简历'?'我的简历':folder,html:'<h1>姓名</h1><p>联系方式与求职方向</p><h2>教育背景</h2><p>点击开始编辑</p><h2>实习经历</h2><p>在这里写入经历内容</p><h2>技能</h2><p>补充技能方向</p>'};resumes.push(r);$('#dialog').close();openResume(r.id);if(jd)createOutline(jd)}
if(a==='folder')modal('新建文件夹','<input id="name" placeholder="文件夹名称">','create-folder');if(a==='create-folder'){const n=$('#name').value.trim();if(!n)return;if(!folders.includes(n))folders.push(n);folder=n;$('#dialog').close();render()}
if(a==='new-node')modal('新建经历文档','<input id="name" placeholder="文档标题">','create-node');if(a==='create-node'){const n=$('#name').value.trim();if(!n)return;nodes.push({title:n,type:1,text:'# '+n+'\n\n'});$('#dialog').close();openDoc(nodes.length-1)}
if(a==='save')save();if(a==='save-doc')saveDoc();if(a==='rename'||a==='save-as')modal(a==='rename'?'重命名简历':'另存简历',`<input id="name" value="${esc(current().name)}">`,a==='rename'?'do-rename':'do-copy');if(a==='do-rename'){current().name=$('#name').value.trim()||current().name;$('#dialog').close();save();render()}
if(a==='copy'||a==='do-copy'){const r={...current(),id:Date.now(),name:a==='copy'?current().name+' · 副本':$('#name').value.trim()||current().name+' · 副本'};resumes.push(r);$('#dialog').close();openResume(r.id);save()}
if(a==='questions')requestGuidance();if(a==='close-outline'){outline=null;render()}if(a==='revise-outline')reviseCurrentOutline();if(a==='compose-resume')composeCurrentResume();if(a==='suggest'){if(screen==='wiki'){$('#chat').placeholder=b.textContent+'：请写下你实际做过的事、背景和结果';$('#chat').focus()}else $('#chat').value=b.textContent;}if(a==='send'){const t=$('#chat').value.trim();if(!t)return;$('#chat').value='';requestAssistance(t)}if(a==='demo-review'){const quote='整理团队协作中的重复步骤，明确各阶段需要交付的内容。';if(!$('#paper').textContent.includes(quote)){toast('当前正文没有对应的示例段落；请打开示例简历体验。');return}current().review={quote};render();locateReview()}
if(a==='locate-review')locateReview();if(a==='resolve-review'||a==='dismiss-review'){delete current().review;render();toast(a==='resolve-review'?'建议已标记处理，正文保持当前编辑内容':'已忽略这条示例建议')}
});
async function loadConversation(){const expId=selectedExperience();if(!expId)return;try{const response=await fetch(`/api/wiki/conversation?experience_id=${encodeURIComponent(expId)}`);if(!response.ok)return;const data=await response.json();wikiMessages[expId]=(data.messages||[]).map(turn=>{const user=turn.user?`<div class="bubble">${esc(turn.user)}</div>`:'';const assistant=turn.status==='guidance'?`<p>${(turn.assistant?.questions||[]).map(q=>`<strong>可补充：</strong>${esc(q.question)}<small>依据：${esc(q.basis)}</small>`).join('<br>')}</p>`:turn.status==='rejected'?`<p>未归入这段经历：${esc(turn.assistant)}</p>`:`<p>已归入这段经历。${(turn.assistant?.questions||[]).map(q=>`<br>可补充：${esc(q)}`).join('')}</p>`;return user+assistant}).join('');if(selectedExperience()===expId&&$('#messages'))$('#messages').innerHTML=wikiMessages[expId]}catch(e){toast(`对话读取失败：${e.message}`)}}
async function requestGuidance(){const expId=selectedExperience();if(!expId){toast('请先选择一个已有经历节点');return}try{toast('正在查看这段经历还可以补充什么…');const result=await postJson('/api/wiki/questions',{experience_id:expId});await loadConversation();if(!result.questions?.length)toast('这段经历目前没有明确的补充问题')}catch(e){toast(`引导提问失败：${e.message}`)}}
async function requestAssistance(instruction){if(screen==='wiki'){const expId=selectedExperience();if(!expId){toast('请先选择一个已有经历节点');return}try{toast('正在核对内容与所选经历的关系…');const result=await postJson('/api/wiki/input',{message:instruction,experience_id:expId});await loadWiki(expId);await loadConversation();toast(`已归入所选经历 · 快照 ${result.revision}`)}catch(e){await loadConversation();if($('#chat'))$('#chat').value=instruction;toast(`未归入经历：${e.message}`)}return}const content=$('#paper')?.innerText;if(!content){toast('请先填写正文');return}const box=$('#messages');box.insertAdjacentHTML('beforeend',`<div class="bubble">${esc(instruction)}</div><p>正在分析当前正文…</p>`);const pending=box.lastElementChild;try{const result=await postJson('/api/assist',{task:'review',content,instruction});pending.remove();const comments=result.comments||[];if(!comments.length){box.insertAdjacentHTML('beforeend','<p>当前没有可定位的具体建议。</p>');return}current().review={quote:comments[0].quote,suggestion:comments[0].suggestion};box.insertAdjacentHTML('beforeend',`<p>已生成 ${comments.length} 条建议，第一条已标注在正文旁。${comments.slice(1).map(c=>`<br>「${esc(c.quote)}」：${esc(c.suggestion)}`).join('')}</p>`);const html=box.innerHTML;render();$('#messages').innerHTML=html}catch(e){pending.textContent=`请求未完成：${e.message}`}}
function locateReview(){const quote=current()?.review?.quote;if(!quote)return;const el=[...$('#paper').querySelectorAll('li,p')].find(el=>el.textContent.includes(quote));if(!el){toast('原文已改动，建议仍保留供参考');return}el.scrollIntoView({block:'center',behavior:'smooth'});el.classList.add('review-focus');setTimeout(()=>el.classList.remove('review-focus'),2200)}
async function postJson(url,data){const res=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),out=await res.json();if(!res.ok)throw Error(out.error||'操作失败');return out}
async function loadWiki(openId){try{const response=await fetch('/api/wiki');if(!response.ok)throw Error('服务未就绪');const data=await response.json();wikiRevision=data.index.revision;wikiRelations=data.index.relations||[];if(!wikiRevision)return;const activeId=nodes[activeDoc]?.id||null,openIds=docTabs.map(i=>nodes[i]?.id),root=nodes[0],basic=nodes[1];nodes.splice(0,nodes.length,root,basic);for(const n of data.index.nodes){if(n.status!=='active')continue;const document=data.documents.find(d=>d.id===n.id);nodes.push({id:n.id,experience_id:n.experience_id,kind:n.kind,title:n.title,type:n.kind==='topic'?0:['story','fragment'].includes(n.kind)?2:1,text:document?.markdown||n.summary})}const indexOf=id=>nodes.findIndex(n=>n.id===id);docTabs=[1,...openIds.map(indexOf).filter(i=>i>1)];if(openId){const i=indexOf(openId);if(i>=0){activeDoc=i;if(!docTabs.includes(i))docTabs.push(i)}}else if(activeId){const i=indexOf(activeId);activeDoc=i>=0?i:1}else activeDoc=1;render();loadConversation()}catch(e){toast(`经历库读取失败：${e.message}`)}}
async function saveDoc(){const n=nodes[activeDoc];if(!n)return;if(activeDoc===0){toast('总览节点由经历索引自动生成');return}if(activeDoc===1){try{await postJson('/api/profile',{markdown:n.text});toast('基础信息已保存到本机资料库')}catch(e){toast(`基础信息未保存：${e.message}`)}return}try{if(!n.id){if(n.text.replace(/^#.*$/m,'').trim().length<8){toast('请先填写经历正文再保存');return}const created=await postJson('/api/wiki/create',{message:n.text});nodes.splice(activeDoc,1);docTabs=docTabs.filter(i=>i!==activeDoc);await loadWiki(created.experience_id);toast('经历已建立并加入索引');return}await postJson('/api/wiki/edit',{experience_id:n.experience_id||n.id,node_id:n.id,markdown:n.text});toast('经历正文和索引已保存');await loadWiki(n.experience_id||n.id)}catch(e){toast(`未保存：${e.message}`)}}
async function createOutline(jd){try{toast('正在分析 JD 并生成大纲…');const run=await postJson('/api/resume/outline',{jd,mode:'index_fallback'});runId=run.id;outline=run.outline;runDetail=run;runReview=null;current().jd=jd;render()}catch(e){toast(`大纲生成失败：${e.message}`)}}
async function reviseCurrentOutline(){const comment=$('#outline-comment')?.value.trim();if(!comment)return;try{const run=await postJson('/api/resume/revise',{run_id:runId,comment});outline=run.outline;runDetail=run;runReview=null;render()}catch(e){toast(`大纲修订失败：${e.message}`)}}
const markdownHtml=md=>{const inline=value=>esc(value).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');return md.split('\n').map(line=>line.startsWith('# ')?`<h1>${inline(line.slice(2))}</h1>`:line.startsWith('## ')?`<h2>${inline(line.slice(3))}</h2>`:line.startsWith('### ')?`<h3>${inline(line.slice(4))}</h3>`:line.trim()?`<p>${inline(line.replace(/^[-*] /,''))}</p>`:'').join('')};
async function composeCurrentResume(){try{toast('正在根据大纲和完整经历生成正文…');const run=await postJson('/api/resume/compose',{run_id:runId});if(!run.validation?.ok||!run.content?.markdown){runReview={issues:run.validation?.issues||[{type:'校验',reason:'未通过最终校验'}],markdown:run.content?.markdown||''};render();toast('成稿需要检查，具体问题已展开');return}current().html=markdownHtml(run.content.markdown);current().runId=runId;outline=null;runReview=null;render();await save(false);toast('正文已生成并通过校验')}catch(e){toast(`正文生成失败：${e.message}`)}}
async function loadProfile(){try{const response=await fetch('/api/profile');if(!response.ok)return;const saved=await response.json();if(saved.markdown){nodes[1].text=saved.markdown;if(activeDoc===1&&screen==='wiki')render()}}catch(e){toast(`基础信息读取失败：${e.message}`)}}
async function loadResumes(){try{const response=await fetch('/api/resumes');if(!response.ok)throw Error('服务未就绪');resumes=(await response.json()).items||[];render()}catch(e){toast(`简历列表读取失败：${e.message}`)}}
async function loadSyncStatus(){try{const response=await fetch('/api/sync/settings');const info=await response.json();const target=$('#sync-status');if(target)target.textContent=`${info.configured?'令牌已配置':'尚未配置令牌'} · ${info.last_sync?.last_push?'最近同步：'+info.last_sync.last_push:'尚未同步'}`}catch(e){if($('#sync-status'))$('#sync-status').textContent=`同步状态读取失败：${e.message}`}}
async function saveSyncConfig(){try{await postJson('/api/sync/settings',{token:$('#sync-token').value.trim()});$('#sync-token').value='';await loadSyncStatus();toast('私有仓库访问令牌已保存在本机')}catch(e){toast(e.message)}}
async function runSync(action){try{toast(action==='push'?'正在同步本机资料…':'正在检查云端备份…');await postJson(`/api/sync/${action}`,{});await loadSyncStatus();if(action==='pull'){await loadWiki();await loadProfile();await loadResumes()}toast(action==='push'?'资料已同步到私有仓库':'资料已从私有仓库恢复')}catch(e){toast(`同步失败：${e.message}`)}}
render();loadWiki();loadProfile();loadResumes();

